import { readFileSync, writeFileSync } from 'fs';
import { join } from 'path';
import { buildPersonaFromProfile, type MatchableProfile } from './job-matching.service';

// The matching evaluation (apps/matching-service/eval) scores synthetic
// profiles. They must reach the scorer the same way real ones do — through
// buildPersonaFromProfile — so the persona file is generated by this adapter
// and this spec fails when the committed file no longer matches it.
// Regenerate after an intentional adapter change:
//   WRITE_EVAL_PERSONAS=1 npx jest src/matching/eval-personas.spec.ts
const EVAL_DIR = join(__dirname, '../../../matching-service/eval');

interface EvalProfile {
  evalId: string;
  split: 'dev' | 'heldout';
  expectNoEmail?: boolean;
  profile: Omit<MatchableProfile, 'experiences'> & {
    experiences: { title: string; company: string; description: string; startDate: string; endDate: string | null }[];
  };
}

function buildPersonas() {
  const profiles = JSON.parse(readFileSync(join(EVAL_DIR, 'profiles.json'), 'utf8')) as EvalProfile[];
  return profiles.map((p) => ({
    evalId: p.evalId,
    split: p.split,
    expectNoEmail: p.expectNoEmail ?? false,
    persona: buildPersonaFromProfile({
      ...p.profile,
      experiences: p.profile.experiences.map((e) => ({
        ...e,
        startDate: new Date(e.startDate),
        endDate: e.endDate ? new Date(e.endDate) : null,
      })),
    } as MatchableProfile),
  }));
}

describe('matching evaluation personas', () => {
  const target = join(EVAL_DIR, 'personas.generated.json');

  it('every evaluation profile has a fixed end date so its experience is deterministic', () => {
    const profiles = JSON.parse(readFileSync(join(EVAL_DIR, 'profiles.json'), 'utf8')) as EvalProfile[];
    for (const p of profiles) for (const e of p.profile.experiences) expect(e.endDate).toBeTruthy();
  });

  it('personas.generated.json is exactly what the production adapter builds', () => {
    const built = `${JSON.stringify(buildPersonas(), null, 2)}\n`;
    if (process.env.WRITE_EVAL_PERSONAS === '1') writeFileSync(target, built);
    expect(readFileSync(target, 'utf8')).toBe(built);
  });
});
